dist[1], ways[1] = 0, 1
while heap:
    d, u = heappop(heap)
    if d > dist[u]:
        continue
    for v, w in adj[u]:
        if d + w < dist[v]:
            dist[v] = d + w
            ways[v] = ways[u]                 # a better route: forget the old count
            heappush(heap, (dist[v], v))
        elif d + w == dist[v]:
            ways[v] = (ways[v] + ways[u]) % MOD

