#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, long long>>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back({(int)e[1], e[2]});
        adj[e[1]].push_back({(int)e[0], e[2]});
    }
    const long long MOD = 1000000007LL, INF = 1000000000000000000LL;
    vector<long long> dist(n + 1, INF), ways(n + 1, 0);
    dist[1] = 0;
    ways[1] = 1;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> heap;
    heap.push({0, 1});
    while (!heap.empty()) {
        pair<long long, int> top = heap.top();
        heap.pop();
        int u = top.second;
        if (top.first > dist[u]) continue;
        for (const auto& edge : adj[u]) {
            int v = edge.first;
            long long next = top.first + edge.second;
            if (next < dist[v]) {
                dist[v] = next;
                ways[v] = ways[u];
                heap.push({next, v});
            } else if (next == dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
            }
        }
    }
    cout << (dist[n] < INF ? ways[n] % MOD : -1) << "\n";

    return 0;
}

